export function storyScene(story,line){
 const scene=scenes[story.id]?.[line];if(!scene)throw Error('Missing story scene: '+story.id+' '+line);
 const sky=scene.background==='room'?'#f7efdf':'#e5f0f4';
 let background='<rect width="600" height="300" rx="20" fill="'+sky+'"/><path d="M0 226h600v74H0Z" fill="'+(scene.background==='sea'?'#ead5ab':scene.background==='room'?'#e5d6c1':'#d6e0c4')+'"/>';
 if(scene.background==='sea')background+='<path d="M0 160q100-20 200 0t200 0 200 0v78H0Z" fill="#9dcbd6"/><path d="M0 180q75-15 150 0t150 0 150 0 150 0M0 207q100-15 200 0t200 0 200 0" stroke="#d6edf0" stroke-width="4" fill="none"/>';
 if(scene.background==='path')background+='<path d="M214 300 293 126h33l89 174Z" fill="#d4bda1"/>';
 if(scene.background==='station')background+='<path d="M380 300 435 126m85 174-46-174" stroke="#7b8c94" stroke-width="6"/><path d="M406 251h87m-81-34h75m-65-30h55" stroke="#a7a38e" stroke-width="6"/>';
 const art=scene.objects.map(({name,x,y,w,h})=>'<g data-object="'+name+'" transform="translate('+(x-w/2)+' '+(y-h)+') scale('+w/100+' '+h/100+')">'+symbols[name]+'</g>').join('');
 return '<svg class="sentence-scene" viewBox="0 0 600 300" role="img" aria-label="'+esc(story.sentences[line])+'"><title>'+esc(story.sentences[line])+'</title>'+background+art+scene.extras+'</svg>';
}
